'use strict';

// MODULES //

var Int64 = require( '@stdlib/number/int64/ctor' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Evaluates the identity function for a signed 64-bit integer `x`.
*
* @private
* @param {Int64} x - input value
* @returns {Int64} input value
*
* @example
* var Int64 = require( '@stdlib/number/int64/ctor' );
*
* var x = new Int64( 1 );
* var v = identity( x );
* // returns <Int64>[ 1n ]
*
* @example
* var Int64 = require( '@stdlib/number/int64/ctor' );
*
* var x = new Int64( 0 );
* var v = identity( x );
* // returns <Int64>[ 0n ]
*
* @example
* var Int64 = require( '@stdlib/number/int64/ctor' );
*
* var x = new Int64( 4294967296 );
* var v = identity( x );
* // returns <Int64>[ 4294967296n ]
*
* @example
* var Int64 = require( '@stdlib/number/int64/ctor' );
*
* var x = new Int64( -1000000000000 );
* var v = identity( x );
* // returns <Int64>[ -1000000000000n ]
*/
function identity( x ) {
	return new Int64( addon( x.valueOf() ) );
}


// EXPORTS //

module.exports = identity;
